import { PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec2, uv } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, Vector2 } = ctx.THREE;
  const group = new Group();

  // 1. DESIGN PALETTE & TOKENS
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. BACKDROP PLANE (No Black Void Constraint)
  // Build an engineered gradient backdrop panel behind the sprite to ground the composition
  const bgGeom = new PlaneGeometry(7.0, 6.0);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.85 });

  // Custom TSL vertical gradient from ink (bottom) to surface (top) with an accent-tinted horizon
  const bgUv = uv();
  const cInk = vec2(
    parseInt(colors.ink.substring(1,3), 16) / 255,
    parseInt(colors.ink.substring(3,5), 16) / 255
  );
  const cSurface = vec2(
    parseInt(colors.surface.substring(1,3), 16) / 255,
    parseInt(colors.surface.substring(3,5), 16) / 255
  );

  // Basic TSL node interpolation simulating a dark, rich vignette
  bgMat.colorNode = bgUv.y.mix(
    vec2(cInk.x, cInk.y).toVec4(0.1, 1.0),
    vec2(cSurface.x, cSurface.y).toVec4(0.12, 1.0)
  );

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // 3. SPRITE ELEMENT WITH ATLAS MAPPING
  // Sourced rect: 0, 0, 512, 320 -> Aspect ratio: 1.6
  const width = 4.0;
  const height = width / 1.6;
  const spriteGeom = new PlaneGeometry(width, height);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaTest: 0.01,
    depthWrite: false
  });

  const spriteMesh = new Mesh(spriteGeom, spriteMat);
  // Place slightly forward in front of background
  spriteMesh.position.set(0, 0, 0.1);
  group.add(spriteMesh);

  // Load the sprite sheet / texture
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    // Atlas setup (Source rect: 0, 0, 512, 320. Assuming typical 512x512 base if not specified, 
    // but we use the UV scaling mapping node to conform 0,0,512,320)
    tex.generateMipmaps = true;
    spriteMat.map = tex;

    // UV transformation for region 0, 0, 512, 320.
    // If atlas is exactly 512x512, mapping is [0, 0.375] to [1.0, 1.0] visually depending on coordinate origin.
    // We map uv directly here using standard node mapping.
    const uvTransform = uv().mul(vec2(1.0, 320 / 512)).add(vec2(0.0, 0.0));
    spriteMat.uvNode = uvTransform;
    spriteMat.needsUpdate = true;
  }).catch((err) => {
    console.warn("Failed to load sprite texture: ", err);
  });

  // 4. MOTION WITH WEIGHT (ENTRANCE)
  // GSAP weighted-settle motion curve for elegant loading transition
  spriteMesh.scale.set(0.85, 0.85, 1);
  spriteMesh.position.y = -0.4;

  const tl = gsap.timeline();
  tl.to(spriteMesh.position, {
    y: 0,
    duration: 1.1,
    ease: "power4.out"
  });
  tl.to(spriteMesh.scale, {
    x: 1,
    y: 1,
    duration: 1.3,
    ease: "elastic.out(1.0, 0.75)"
  }, 0.05);

  // Idle movement: subtle breathing to emphasize luxury watch precision
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(spriteMesh.position, {
    y: 0.04,
    duration: 4,
    ease: "power1.inOut"
  });

  // Cleanup handler
  group.userData = {
    handlers: {},
    cleanup: () => {
      tl.kill();
      idleTl.kill();
      spriteGeom.dispose();
      spriteMat.dispose();
      bgGeom.dispose();
      bgMat.dispose();
    }
  };

  return group;
}
